    sendMessage: {
        parameters: {
            query?: never;
            header?: {
                /** @description Retry key retained for 24 hours. Reuse the same key and identical request-body bytes to receive the original response. A different body returns 422; a concurrent request returns 409. */
                "idempotency-key"?: string;
            };
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["MessageCreation"];
            };
        };
        responses: {
            /** @description Campaign accepted for sending or scheduling. */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Message"];
                };
            };
            /** @description The key may not send. A mobile key never can. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description This `dedup_key` has already been used, or a request under this `Idempotency-Key` is still running. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description The payload would show nothing, claims the reserved `carillon` data key, a device or a saved audience is not in this app, `delivery_rate` is above the app ceiling, or this `Idempotency-Key` was used with a different body. */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
        };
    };
